<script setup lang="ts">
import {computed,ref} from 'vue'
import {useRoute} from 'vue-router'
import {useDb} from '../../../stores/db'
import {useSession} from '../../../stores/session'
import {StatusBadge,LaneCard,Timeline,AgeChip} from '../../../components/shared'
import {fmtMoney} from '../../../lib/money'
import {markBooked,markSold} from '../domain'
const route=useRoute(),db=useDb(),session=useSession(),tab=ref('chronology'),margin=ref(80),message=ref('')
const caseRow=computed(()=>db.data.cases.find(c=>c.id===route.params.id)),booking=computed(()=>db.data.bookings.find(b=>b.caseId===caseRow.value?.id)),unit=computed(()=>db.data.units.find(u=>u.id===booking.value?.unitId)),project=computed(()=>db.data.projects.find(p=>p.id===booking.value?.projectId)),purchasers=computed(()=>booking.value?.parties.map(p=>db.data.people.find(person=>person.id===p.personId))??[])
const loans=computed(()=>db.data.loanApplications.filter(l=>l.caseId===caseRow.value?.id)),matters=computed(()=>db.data.legalMatters.filter(m=>m.caseId===caseRow.value?.id)),events=computed(()=>db.data.caseEvents.filter(e=>e.caseId===caseRow.value?.id))
function booked(){if(!booking.value)return;try{markBooked(booking.value.id);message.value='Booking is BOOKED.'}catch(e){message.value=e instanceof Error?e.message:''}}
function sold(){if(!booking.value)return;try{markSold(booking.value.id,margin.value*100);message.value='Booking is SOLD.'}catch(e){message.value=e instanceof Error?e.message:''}}
</script>
<template><div v-if="caseRow&&booking" class="page"><header class="page-header"><div><p class="eyebrow">{{caseRow?.id}} · {{project?.name}} · {{unit?.unitNo}}</p><h1>Booking {{booking?.id}}</h1><p>Price {{fmtMoney(booking?.priceSnapshot.listPriceMinor??null)}} · Fee {{fmtMoney(booking?.bookingFee.agreedMinor??null)}} · {{purchasers.map(p=>p?.name).join(' + ')}}</p></div><StatusBadge :label="booking?.status||'Unknown'"/></header><p v-if="message" class="card">{{message}}</p><div class="card-grid"><LaneCard title="Financing" :state="loans.map(l=>l.stage).join(' / ')||'No applications'" owner="Bank owners" next="Resolve unmet offer condition"/><LaneCard title="Legal" :state="matters.map(m=>`${m.kind}: ${m.stage}`).join(' / ')" owner="Firm A / Firm B" next="Confirm SPA signing window"/><LaneCard title="Construction" :state="db.data.constructionUpdates.find(c=>c.blockId===unit?.blockId&&c.published)?.stage||'No update'" owner="Developer" next="Next expected update 1 Dec"/><LaneCard title="Purchase money" state="RM5,000 outstanding" owner="Finance" next="Verify pending evidence"/><LaneCard title="Handover" :state="db.data.handovers.find(h=>h.caseId===caseRow?.id)?.openIssues.length?'Issues open':'Not ready'" owner="Operations" next="Close utility-meter clearance"/></div><div class="actions"><el-button v-for="name in ['chronology','tasks','documents','commission','audit']" :key="name" :type="tab===name?'primary':''" @click="tab=name">{{name}}</el-button></div><section class="card"><div v-if="tab==='chronology'"><h2>Chronology</h2><AgeChip :gross="20" :active="18" :overdue="2"/><Timeline :events="events"/></div><div v-else-if="tab==='tasks'"><h2>Tasks and blockers</h2><p v-for="task in db.data.tasks.filter(t=>t.caseId===caseRow?.id)" :key="task.id" class="data-row"><span><strong>{{task.title}}</strong><br>{{task.blocker?.cause||'No blocker'}}</span><StatusBadge :label="task.state"/></p></div><div v-else-if="tab==='documents'"><h2>Documents</h2><p v-for="doc in db.data.documents" :key="doc.id"><StatusBadge :label="doc.state"/> {{doc.purpose}}</p></div><div v-else-if="tab==='commission'"><h2>Commission and settlement</h2><p v-if="['admin','finance_preparer','finance_approver','finance_executor','leadership'].includes(session.activePersona?.activeRole||'')">Restricted finance view. Eligible base and separate PIVO fee are shown in Finance.</p><p v-else>Commission data is not available for this role.</p></div><div v-else><h2>Audit</h2><p v-for="entry in db.data.auditEntries.slice(0,4)" :key="entry.id">{{entry.action}} · {{entry.target}} · {{entry.at}}</p></div></section><div class="card actions"><el-button @click="booked">Check BOOKED gates</el-button><label>Loan margin %<input v-model.number="margin" type="number"></label><el-button @click="sold">Mark SOLD</el-button></div></div></template>
